from celsius import to_fahrenheit


def test_freezing_and_boiling_points():
    assert to_fahrenheit(0) == 32.0
    assert to_fahrenheit(100) == 212.0


def test_negative_temperatures():
    assert to_fahrenheit(-40) == -40.0
    assert to_fahrenheit(-10) == 14.0


def test_whole_temperatures():
    assert to_fahrenheit(25) == 77.0
    assert to_fahrenheit(5) == 41.0
